/*
 * Catalog content (written for WorkoutPro, PT-BR). Mapping onto the app's MuscleGroup union:
 * adutores -> Quadríceps, abdutores/glúteo médio -> Glúteo, oblíquos -> Abdômen,
 * deltoide posterior -> Ombros, isquiotibiais -> Posterior.
 * `imageId` points to a folder of yuhonas/free-exercise-db only when the movement is equivalent.
 */

function x(
  id: string,
  name: string,
  englishName: string,
  aliases: string[],
  muscleGroup: MuscleGroup,
  secondaryMuscles: MuscleGroup[],
  equipment: LibraryEquipment,
  mechanic: LibraryMechanic,
  level: LibraryLevel,
  imageId: string | null,
  instructions: string[],
  mistakes: string[],
): LibraryExercise {
  return { id, name, englishName, aliases, muscleGroup, secondaryMuscles, equipment, mechanic, level, imageId, instructions, mistakes }
}

